package com.bank.heatmap;

import java.util.Arrays;
import java.util.logging.Logger;

// Repaints a connected same-status region of a risk heat map.
public class HeatMapFiller {

    private static final Logger log = Logger.getLogger(HeatMapFiller.class.getName());

    public int[][] fill(int[][] image, int sr, int sc, int newStatus) {
        int original = image[sr][sc];
        if (original == newStatus) {           // guard: no-op, avoid infinite loop
            log.info("New status equals original; no change");
            return image;
        }
        dfs(image, sr, sc, original, newStatus);
        log.info("Filled region; result=" + Arrays.deepToString(image));
        return image;
    }

    private void dfs(int[][] img, int r, int c, int original, int newStatus) {
        if (r < 0 || c < 0 || r >= img.length || c >= img[0].length) return;
        if (img[r][c] != original) return;     // boundary of the region
        img[r][c] = newStatus;                 // repaint (acts as visited mark)
        dfs(img, r + 1, c, original, newStatus);
        dfs(img, r - 1, c, original, newStatus);
        dfs(img, r, c + 1, original, newStatus);
        dfs(img, r, c - 1, original, newStatus);
    }
}
