package com.bank.heatmap;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class HeatMapDemo {

    private static final Logger log = Logger.getLogger(HeatMapDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Risk Heat Map Reclassify");
        // statuses: 1=low,1=low,...,0=none,2=high
        int[][] image = {
            {1, 1, 1},
            {1, 1, 0},
            {1, 0, 1}
        };
        HeatMapFiller filler = new HeatMapFiller();
        filler.fill(image, 1, 1, 2); // click center, reclassify region to high(2)
    }
}
